// Fake of @minecraft/server-ui for tests. Queue answers in `picks`.
export const picks = [];
export class ActionFormData {
  constructor() { this.b = []; }
  title() { return this; }
  body() { return this; }
  button(t) { this.b.push(t); return this; }
  async show() {
    const s = picks.shift();
    return s === undefined ? { canceled: true } : { selection: typeof s === "string" ? this.b.findIndex((t) => t.startsWith(s)) : s };
  }
}
